import type { BaseVariableConfig } from '../../Variable'

/**
 * Configuration type for checkbox variables
 * Note: selectionRequired cannot be true when hidden or readOnly is true, and vice versa
 * @interface
 */
export type CheckboxVariableType<Type extends boolean = boolean, Default extends Type = Type> = BaseVariableConfig<
    Type,
    Default
> & {
    /** Indicates whether the checkbox must be selected. Cannot be true when readOnly or hidden is true. */
    selectionRequired?: boolean
    /** Indicates whether the field is read-only. Cannot be true when selectionRequired is true. */
    readOnly?: boolean
    /** Indicates whether the field is hidden. Cannot be true when selectionRequired is true. */
    hidden?: boolean
}

/**
 * A CatalogItem variable for a checkbox field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the checkbox variable including:
 *   * **question** - Question text displayed to the user
 *   * **defaultValue**? - Default value for the variable
 *   * **selectionRequired**? - Indicates whether the checkbox must be selected
 *   * **hidden**? - Indicates whether the checkbox is hidden
 *   * **readOnly**? - Indicates whether the checkbox is read only
 *   * And all other properties from the base Variable type
 * @group ServiceCatalog/Variables
 */
export function CheckboxVariable(config: CheckboxVariableType) {
    return config
}
